import math
import random


def buffon_estimate(drops, length, gap, seed):
    """Estimate pi from needle drops (length at most gap)."""
    rng = random.Random(seed)
    hits = 0
    for _ in range(drops):
        centre = rng.uniform(0, gap / 2)
        angle = rng.uniform(0, math.pi / 2)
        if centre <= length / 2 * math.sin(angle):
            hits += 1
    return 2 * length * drops / (gap * hits)
